mapper.select:
select cv_name as cvName, name, phone, mail, shortlink, parse_content as parseContent, process_status as processStatus, update_time as updateTime
from cv_storage
where user_id = #{userId}

select shortlink
from cv_storage
where user_id = #{userId};

select id, shortlink, date, count, create_time, update_time
from cv_monitor
where shortlink=#{shortlink}
  and date between #{beginTime} and #{endTime};

select count(*)
from cv_access_log
where shortlink=#{shortlink}

select ip, browser, os, device, create_time
from cv_access_log
where shortlink=#{shortlink}
ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE cv_access_code
SET accessible_count = accessible_count - 1,
update_time = NOW()
WHERE shortlink = #{shortlink}
AND access_code = #{accessCode}
AND accessible_count > 0
AND available = 1
AND deadline > CURRENT_TIMESTAMP
LIMIT 1;

update cv_storage
set
    deadline = #{time}
where user_id = #{userId}
